BASE = Path(__file__).resolve().parent
random.seed(11)
def n(x):
    s = f"{x:.3f}".rstrip("0").rstrip(".")
    return "0" if s in ("-0", "") else s


def pt(p):
    return f"{n(p[0])},{n(p[1])}"


def seg(pts):
    """Catmull-Rom -> cubic bezier commands, assuming the pen is already at pts[0]."""
    out = []
    m = len(pts)
    for i in range(m - 1):
        p0 = pts[i - 1] if i > 0 else pts[0]
        p1, p2 = pts[i], pts[i + 1]
        p3 = pts[i + 2] if i + 2 < m else pts[-1]
        c1 = (p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6)
        c2 = (p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6)
        out.append(f"C {pt(c1)} {pt(c2)} {pt(p2)}")
    return " ".join(out)


def smooth_closed(pts):
    m = len(pts)
    d = [f"M {pt(pts[0])}"]
    for i in range(m):
        p0, p1, p2, p3 = pts[(i - 1) % m], pts[i], pts[(i + 1) % m], pts[(i + 2) % m]
        c1 = (p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6)
        c2 = (p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6)
        d.append(f"C {pt(c1)} {pt(c2)} {pt(p2)}")
    return " ".join(d) + " Z"


def mix(c1, c2, t):
    a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
    b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
    return "#" + "".join(f"{int(a[i] + (b[i] - a[i]) * t):02x}" for i in range(3))


def label(text, dot, knee, end, fs, anchor, sw, ring=0, ring_sw=0, tcolor="#ffffff"):
    """Leader-line label in the style of the video's 'SNP' tag."""
    x0, y0 = dot
    x1, y1 = knee
    x2, y2 = end
    s = ""
    if ring:
        s += f'<circle cx="{n(x0)}" cy="{n(y0)}" r="{n(ring)}" fill="none" stroke="#fff" stroke-width="{n(ring_sw)}"/>'
    s += (f'<polyline points="{pt(dot)} {pt(knee)} {pt(end)}" fill="none" stroke="#fff" '
          f'stroke-width="{n(sw)}" stroke-linejoin="round" stroke-linecap="round"/>')
    tx = x2 + (fs * 0.25 if anchor == "start" else -fs * 0.25)
    s += (f'<text x="{n(tx)}" y="{n(y2 - fs * 0.22)}" font-size="{n(fs)}" text-anchor="{anchor}" '
          f'fill="{tcolor}" stroke="#0b1230" stroke-opacity=".75" stroke-width="{n(fs * 0.16)}" '
          f'paint-order="stroke" stroke-linejoin="round" class="lbl">{text}</text>')
    return s


# All levels share the same myocardial focal axis. Only scales compose;
# avoiding large cancelling translations also keeps deep zoom numerically stable.
HEART_S = .2 * PARK_BODY_S
PATCH_R = 550.0
PATCH_WORLD_R = 0.08
TS_S = PATCH_WORLD_R / HEART_S / PATCH_R
NS_R = 400.0
NS_S = 10.0 / NS_R
CS_S = 0.30
DS_S = 0.18
LEVELS = [
    dict(id="L0", s=1, rho=700),
    dict(id="L1", s=HEART_S, rho=78),
    dict(id="L2", s=TS_S, rho=PATCH_R),
    dict(id="L3", s=NS_S, rho=NS_R),
    dict(id="L4", s=CS_S, rho=520),
    dict(id="L5", s=DS_S, rho=650),
]

