LEVEL_BOUNDS = [700, 78, 550, 400, 650, 1200]
CELL_TILE_COLS=12
CELL_TILE_ROWS=12
CELL_TILE_W=106*CELL_TILE_COLS
CELL_TILE_H=78*CELL_TILE_ROWS


def cell_pose(row,col):
    # Periodic deterministic jitter keeps the SVG tile seamless, and gives
    # the tissue irregular close packing instead of aligned rows and columns.
    rr,cc=row%CELL_TILE_ROWS,col%CELL_TILE_COLS
    h=(rr*73856093 ^ cc*19349663 ^ 0x5F356495) & 0xffffffff
    h ^= h>>16;h=(h*2246822519)&0xffffffff;h ^= h>>13
    # Cardiac muscle tends to form fibers, but individual cells do not sit on
    # perfectly level rows. Bend those fibers periodically across the tile.
    phase=math.tau*cc/CELL_TILE_COLS+rr*2.3999632297
    jx=round(((h & 255)/255-.5)*42)
    jy=round((((h>>8)&255)/255-.5)*32+24*math.sin(phase))
    if rr==0 and cc==0:jx=jy=0
    variant=(row*3+col+(h>>16)%6)%6
    angle=round((((h>>22)&255)/255-.5)*30+9*math.cos(phase))
    if rr==0 and cc==0:variant=angle=0
    return col*106+(row%2)*53+jx,row*78+jy,variant,angle


CELLS=[]
for row in range(-18,19):
    for col in range(-20,21):
        x,y,variant,angle=cell_pose(row,col)
        # Keep an expanded focal clump; the heart itself remains smooth.
        if row==0 and col==0 or (x/1800)**2+(y/1250)**2>1:continue
        CELLS.append(dict(id=f'neighbor-{len(CELLS)}',x=x,y=y,variant=variant,angle=angle))


