def build_map_country(country):
    code=country['code']
    fill=COUNTRY_COLORS[code]
    name=COUNTRY_NAMES.get(code,country['name'])
    stroke='#d9c89c' if code=='HUN' else '#14283c'
    interaction=f' data-country="{code}" class="zoom-target" role="button" tabindex="0" aria-label="Explore {escape(name)}"'
    s=[f'<g id="country-{code}"{interaction}><title>{escape(name)}</title>',
       f'<path id="country-path-{code}" d="{country["d"]}" fill="{fill}" stroke="{stroke}" stroke-width=".8" stroke-linejoin="round" fill-rule="evenodd"/>']
    if code in COUNTRY_LABELS:
        x,y=country['label']
        if code=='HUN':x+=5;y+=21
        s.append(f'<text id="country-label-{code}" x="{n(x)}" y="{n(y)}" text-anchor="middle" font-size="{10 if code!="HUN" else 12}" font-weight="600" letter-spacing=".6" fill="#172f43" opacity=".8">{COUNTRY_LABELS[code]}</text>')
    return ''.join(s)+'</g>'


def geo_xy(lon,lat):
    def project(lon,lat):
        p0=math.radians(52);p=math.radians(lat);d=math.radians(lon-12)
        k=math.sqrt(2/(1+math.sin(p0)*math.sin(p)+math.cos(p0)*math.cos(p)*math.cos(d)))
        return (1000*k*math.cos(p)*math.sin(d),-1000*k*(math.cos(p0)*math.sin(p)-math.sin(p0)*math.cos(p)*math.cos(d)))
    x,y=project(lon,lat);ox,oy=project(*MAP_PROJECTION_ANCHOR)
    return x-ox,y-oy


BUDAPEST_X, BUDAPEST_Y = geo_xy(*BUDAPEST_ANCHOR)
map_left = MAP_VIEW['cx']-MAP_VIEW['width']/2-BUDAPEST_X
map_right = MAP_VIEW['cx']+MAP_VIEW['width']/2-BUDAPEST_X
map_top = MAP_VIEW['cy']-MAP_VIEW['height']/2-BUDAPEST_Y
map_bottom = MAP_VIEW['cy']+MAP_VIEW['height']/2-BUDAPEST_Y
CAMERA_MAP_VIEW = {'cx': 0, 'cy': 0,
                   'width': 2*max(abs(map_left),abs(map_right)),
                   'height': 2*max(abs(map_top),abs(map_bottom))}


def window_grid(x,y,cols,rows,dx=9,dy=12,w=3,h=5,color='#36596a'):
    d=' '.join(f'M {n(x+c*dx)},{n(y+r*dy)} h {w} v {h} h {-w} Z' for r in range(rows) for c in range(cols))
    return f'<path d="{d}" fill="{color}" stroke="none"/>'


def arch_windows(xs,y,height=10,width=5,color='#355263'):
    d=' '.join(f'M {n(x-width/2)},{y} v {-height+width/2} q {width/2},{-width} {width},0 v {height-width/2} Z' for x in xs)
    return f'<path d="{d}" fill="{color}" stroke="none"/>'


def dome(x,y,r,color='#6b9d8d',onion=False):
    if onion:
        d=f'M {x-r},{y} C {x-r*1.5},{y-r} {x-r*.3},{y-r*1.2} {x},{y-r*2} C {x+r*.3},{y-r*1.2} {x+r*1.5},{y-r} {x+r},{y} Z'
    else:d=f'M {x-r},{y} Q {x-r},{y-r*1.5} {x},{y-r*1.7} Q {x+r},{y-r*1.5} {x+r},{y} Z'
    return f'<path d="{d}" fill="{color}"/><path d="M {x},{n(y-r*(2 if onion else 1.7))} v -5 m -2,2 h 4" fill="none" stroke="#f2c978" stroke-width="1.6"/>'


