def landmark_layout():
    """Resolve label/icon collisions with short leaders to the real coordinates."""
    layout={};occupied=[]
    # Keep the original Italian artwork at its existing positions.
    ordered=sorted(LANDMARKS,key=lambda l:l['country']!='ITA')
    for item in ordered:
        ax,ay=geo_xy(item['lon'],item['lat'])
        scale=.085 if item['country']=='ITA' else .13
        city=item.get('city',item['name'].split(' · ')[0])
        half=max(50*scale,len(city)*.73)
        candidates=[(0,0)]
        if item['country']!='ITA':
            candidates += [(dx,dy) for r in [9,17,25] for dx,dy in [(r,0),(-r,0),(0,-r),(0,r),(r,-r),(-r,-r),(r,r),(-r,r)]]
        def bounds(dx,dy):return (ax+dx-half-1,ay+dy-100*scale-1,ax+dx+half+1,ay+dy+5)
        def cost(offset):
            box=bounds(*offset)
            overlap=sum(max(0,min(box[2],b[2])-max(box[0],b[0]))*max(0,min(box[3],b[3])-max(box[1],b[1])) for b in occupied)
            return overlap*10+math.hypot(*offset)
        dx,dy=(18,-10) if item['id']=='parliament' else min(candidates,key=cost)
        occupied.append(bounds(dx,dy))
        layout[item['id']]=dict(x=ax+dx,y=ay+dy,ax=ax,ay=ay,scale=scale,radius=max(half+100*scale+6,math.hypot(dx,dy)+2))
    return layout


LANDMARK_LAYOUT=landmark_layout()


