def compact_organelle_art(art):
    """Bake tiny symbol transforms and batch equal-color organelle paths."""
    tree = ET.fromstring('<defs>'+art+'</defs>')
    definitions = {el.get('id'):el for el in tree if el.get('id')}
    batches = {}
    style_keys = {'fill','stroke','stroke-width','stroke-opacity','fill-opacity',
                  'stroke-linecap','stroke-linejoin','data-organelle'}

    def walk(el, inherited, pose=None):
        attrs = {**inherited, **{k:v for k,v in el.attrib.items() if k in style_keys}}
        if el.tag == 'title':
            return
        if el.tag == 'use':
            values = [float(v) for v in re.findall(r'-?\d+(?:\.\d+)?',el.get('transform',''))]
            x,y,angle = values
            for child in definitions[el.get('href')[1:]]:
                walk(child, attrs, (x,y,math.radians(angle)))
            return
        if el.tag == 'g':
            for child in el:
                walk(child,attrs,pose)
            return
        if el.tag == 'circle':
            x,y,r = [float(el.get(k,'0')) for k in ('cx','cy','r')]
            d = f'M {n(x-r)},{n(y)} a {n(r)},{n(r)} 0 1,0 {n(2*r)},0 a {n(r)},{n(r)} 0 1,0 {n(-2*r)},0'
        else:
            d = el.get('d')
        if pose:
            x,y,a = pose
            ca,sa = math.cos(a),math.sin(a)
            # The mitochondrial prototype contains absolute M/C/L/Z commands.
            chunks = []
            for command,numbers in re.findall(r'([MCLZ])([^MCLZ]*)',d):
                values = [float(v) for v in re.findall(r'-?\d+(?:\.\d+)?',numbers)]
                points = [pt((x+ca*px-sa*py,y+sa*px+ca*py)) for px,py in zip(values[::2],values[1::2])]
                chunks.append(command+' '+' '.join(points))
            d = ' '.join(chunks)
        key = tuple(sorted((k,v) for k,v in attrs.items() if k!='data-organelle'))
        batch = batches.setdefault(key,dict(paths=[],kind=attrs.get('data-organelle')))
        batch['paths'].append(d)

    walk(definitions['cell-organelles'],{})
    result = ET.Element('g',{'id':'cell-organelles'})
    ET.SubElement(result,'title').text = 'Mitochondria, ER, Golgi, ribosomes, lysosomes, peroxisomes, endosomes, vesicles and cytoskeleton'
    for key,batch in batches.items():
        attrs = dict(key)
        attrs['d'] = ' '.join(batch['paths'])
        if batch['kind']:
            attrs['data-organelle'] = batch['kind']
        ET.SubElement(result,'path',attrs)
    return ET.tostring(result,encoding='unicode')


